window.logsCopied=x=>{const button=document.getElementById('copyLogsButton');if(button){button.disabled=false;button.textContent=button.dataset.readyLabel||'⧉  Copy full logs & errors'}delete button?.dataset.readyLabel;dashboardNotice({message:x?.message||(x?.ok?'Logs and errors copied.':'Could not copy logs and errors.')})};
