window.readerProgressUpdated=x=>{if(booksData?.allBooks){const book=booksData.allBooks.find(b=>Number(b.id)===Number(x.bookId));if(book){book.progress=Number(x.percentage);book.finished=book.manuallyFinished||book.progress>=.97;booksData.finished=booksData.allBooks.filter(b=>b.finished);booksData.reading=booksData.allBooks.filter(b=>b.progress>0&&!b.finished);renderBooks(booksData);renderStatistics()}}};
