// Local annotations: the native bridge persists data and owns all network/file access.
let annotationState={items:[],settings:{},collections:[],review:[],queue:[]},annotationFilters={search:'',source:'',author:'',tag:'',bookId:'',favorite:false,notes:false,archived:false},annotationPreview=null,reviewIndex=0,annotationsLoaded=false;
function annotationPost(action,values={}){post({type:'annotations',action,all:true,...values})}
function annotationFiltered(items=annotationState.items,rules=annotationFilters){const q=(rules.search||'').toLocaleLowerCase();return items.filter(x=>(rules.archived||!x.archived)&&(!rules.favorite||x.favorite)&&(!rules.notes||x.note.trim())&&(!rules.source||x.source===rules.source)&&(!rules.author||x.author.toLocaleLowerCase().includes(rules.author.toLocaleLowerCase()))&&(!rules.tag||x.tags.includes(rules.tag))&&(!rules.bookId||String(x.bookId)===String(rules.bookId))&&(!q||[x.text,x.note,x.title,x.author,...x.tags].join(' ').toLocaleLowerCase().includes(q))).sort((a,b)=>{const order=annotationState.settings.sort;return order==='title'?a.title.localeCompare(b.title):order==='author'?a.author.localeCompare(b.author):order==='oldest'?a.createdAt-b.createdAt:b.createdAt-a.createdAt})}
function annotationSelect(id,value){annotationFilters[id]=value;renderAnnotations()}
function annotationBookOptions(selected='',empty='All books'){const books=new Map((booksData?.allBooks||[]).map(b=>[Number(b.id),{id:Number(b.id),title:b.title,author:b.authors||''}]));for(const x of annotationState.items)if(x.bookId&&!books.has(x.bookId))books.set(x.bookId,{id:x.bookId,title:x.title,author:x.author});return `<option value="">${esc(empty)}</option>`+[...books.values()].filter(b=>b.id>0).sort((a,b)=>a.title.localeCompare(b.title)).map(b=>`<option value="${b.id}" ${String(b.id)===String(selected)?'selected':''}>${esc(b.title)}${b.author?' · '+esc(b.author):''}</option>`).join('')}
function annotationOptions(values,selected,empty){return `<option value="">${esc(empty)}</option>`+values.map(x=>`<option value="${esc(x)}" ${x===selected?'selected':''}>${esc(x)}</option>`).join('')}
function annotationCard(x){return `<article class="annotation-card ${x.archived?'annotation-archived':''}" data-color="${esc(x.color)}"><div class="annotation-meta"><b>${esc(x.title)}</b><span>${esc(x.source)}${x.archived?' · Archived':''}${x.favorite?' · ★':''}</span></div><blockquote>${esc(x.text)}</blockquote>${x.note?`<p class="annotation-note">${esc(x.note)}</p>`:''}<p class="hint">${esc(x.author)}${x.location.chapter?' · '+esc(x.location.chapter):''}${x.location.percentage!==undefined?' · '+Math.round(x.location.percentage*100)+'%':''}</p><div class="annotation-tags">${x.tags.map(t=>`<span>#${esc(t)}</span>`).join('')}</div><div class="annotation-actions"><button class="small-btn" data-annotation="open" data-id="${esc(x.id)}">${x.bookId?'Open in book':x.source==='Readwise'?'Open in Readwise':'Open source'}</button><button class="small-btn" data-annotation="edit" data-id="${esc(x.id)}">Notes & tags</button><button class="small-btn" data-annotation="favorite" data-id="${esc(x.id)}">${x.favorite?'Unfavorite':'Favorite'}</button><button class="small-btn" data-annotation="archive" data-id="${esc(x.id)}">${x.archived?'Restore':'Archive'}</button><button class="small-btn" data-annotation="enqueue" data-id="${esc(x.id)}">Queue export</button></div></article>`}
function renderAnnotations(){const root=document.getElementById('annotationList');if(!root)return;const items=annotationFiltered();root.className='annotation-list '+(annotationState.settings.view==='cards'?'annotation-grid':'');root.innerHTML=items.slice(0,annotationLimit).map(annotationCard).join('')||'<div class="empty-books">No matching highlights. Save a passage in the reader, import a file, or add one manually.</div>';document.getElementById('annotationCount').textContent=`${items.length} highlights`;document.getElementById('annotationMore').hidden=items.length<=annotationLimit;const unique=key=>[...new Set(annotationState.items.map(x=>x[key]).filter(Boolean))].sort();document.getElementById('annotationBook').innerHTML=annotationBookOptions(annotationFilters.bookId);document.getElementById('annotationSource').innerHTML=annotationOptions(unique('source'),annotationFilters.source,'All sources');document.getElementById('annotationTag').innerHTML=annotationOptions([...new Set(annotationState.items.flatMap(x=>x.tags))].sort(),annotationFilters.tag,'All tags');document.getElementById('annotationCollections').innerHTML=annotationState.collections.map(c=>`<button class="small-btn" data-collection="${esc(c.id)}">${c.pinned?'★ ':''}${esc(c.name)}</button><button class="small-btn" aria-label="${c.pinned?'Unpin':'Pin'} ${esc(c.name)}" data-pin-collection="${esc(c.id)}">${c.pinned?'Unpin':'Pin'}</button><button class="small-btn" aria-label="Remove collection ${esc(c.name)}" data-delete-collection="${esc(c.id)}">Remove</button>`).join('');renderAnnotationQueue();renderAnnotationConflicts()}
let annotationLimit=60;
function annotationEdit(id){const x=annotationState.items.find(x=>x.id===id);if(!x)return;const form=document.getElementById('annotationEditorForm');form.elements.id.value=id;form.elements.title.value=x.title;form.elements.author.value=x.author;form.elements.text.value=x.text;for(const k of ['title','author','text'])form.elements[k].readOnly=true;form.elements.note.value=x.note;form.elements.tags.value=x.tags.join(', ');annotationTagSuggestions();form.elements.bookId.innerHTML=annotationBookOptions(x.bookId,'Not linked to a local book');form.elements.frequency.value=x.frequency;form.elements.color.value=x.color;document.getElementById('annotationEditorTitle').textContent='Notes & tags';document.getElementById('annotationEditor').showModal()}
function annotationTagSuggestions(){document.getElementById('annotationTagSuggestions').innerHTML=annotationState.settings.suggestTags?[...new Set(annotationState.items.flatMap(x=>x.tags))].map(t=>`<option value="${esc(t)}"></option>`).join(''):''}
function annotationNew(){annotationTagSuggestions();const form=document.getElementById('annotationEditorForm');form.reset();form.elements.bookId.innerHTML=annotationBookOptions('','Not linked to a local book');form.elements.id.value='';for(const k of ['title','author','text'])form.elements[k].readOnly=false;form.elements.color.value=annotationState.settings.color||'yellow';document.getElementById('annotationEditorTitle').textContent='Add a passage';document.getElementById('annotationEditor').showModal()}
function renderAnnotationQueue(){const target=document.getElementById('annotationQueue');if(!target)return;const q=annotationState.queue;target.innerHTML=q.length?q.slice(0,50).map(j=>{const item=annotationState.items.find(x=>x.id===j.highlight);return `<div class="annotation-job"><div><b>${esc(item?.title||'Highlight')}</b><p>${esc({readwise:'Readwise Highlights',reader:'Readwise Reader',crosspoint:'CrossPoint annotations'}[j.destination])} · ${esc(j.status)} · ${j.attempts} attempts</p><small>${esc(j.message)}${j.updated?' · '+esc(new Date(j.updated*1000).toLocaleString()):''}</small></div>${['failed','uncertain'].includes(j.status)?`<button class="small-btn" data-retry="${esc(j.id)}" data-uncertain="${j.status==='uncertain'}">Review & retry</button>`:''}</div>`}).join(''):'<p class="hint">No queued uploads. Enable destinations in Settings; new local highlights will be queued.</p>'}
function renderReview(){const root=document.getElementById('annotationReview');if(!root)return;const cards=annotationState.review;reviewIndex=Math.min(reviewIndex,Math.max(0,cards.length-1));const x=cards[reviewIndex];root.innerHTML=x?`<p class="hint">${reviewIndex+1} of ${cards.length} available · No streaks or scores</p>${annotationCard(x)}<div class="annotation-actions"><button class="btn secondary" data-review="skip">Skip for now →</button><button class="btn secondary" data-review="1">Tomorrow</button><button class="btn primary" data-review="7">Keep · next week</button><button class="btn secondary" data-review="30">In a month</button></div>`:'<div class="empty-books">You’re up to date. New highlights, your review schedule, and snoozing determine what appears here.</div>'}
function annotationCheckbox(name,label,value){return `<label class="annotation-check"><input type="checkbox" name="${name}" ${value?'checked':''}>${label}</label>`}
function renderAnnotationSettings(){const root=document.getElementById('annotationSettings');if(!root||root.contains(document.activeElement))return;const s=annotationState.settings;const select=(name,label,opts)=>`<label>${label}<select name="${name}">${opts.map(([v,t])=>`<option value="${v}" ${s[name]===v?'selected':''}>${t}</option>`).join('')}</select></label>`;root.innerHTML=`<form id="annotationPreferencesForm" class="annotation-settings"><fieldset><legend>Reading</legend>${annotationCheckbox('rememberPerBook','Remember appearance separately for each book',s.rememberPerBook)}${annotationCheckbox('restorePosition','Restore last reading position',s.restorePosition)}${select('defaultReader','Open books with',[['shelf','Shelf reader'],['system','Default macOS app']])}<p class="hint">Reader appearance: choose the Appearance button while reading. Shortcuts: arrows turn pages; Home/End jump. In Review, Enter keeps a passage and → skips.</p></fieldset><fieldset><legend>Highlights & notes</legend>${select('sort','Sort by',[['newest','Newest first'],['oldest','Oldest first'],['title','Book title'],['author','Author']])}${select('view','Library view',[['list','List'],['cards','Cards']])}${select('color','Default color',[['yellow','Yellow'],['green','Green'],['blue','Blue'],['pink','Pink']])}${annotationCheckbox('suggestTags','Suggest existing tags when editing',s.suggestTags)}${annotationCheckbox('showArchived','Show archived highlights by default',s.showArchived)}<p class="hint">Archiving affects Shelf only. Passage text and source identities remain unchanged; personal notes and tags are editable.</p></fieldset><fieldset><legend>Sync & connections</legend><p>Choose destinations for new highlights. Existing highlights stay local until you choose Queue export.</p>${annotationCheckbox('readwiseAutoImport','Keep my Readwise library up to date automatically',s.readwiseAutoImport)}<details><summary>Sending highlights and Reader progress</summary>${annotationCheckbox('autoSync','Send queued highlights automatically while Shelf is open',s.autoSync)}${['readwise','reader','crosspoint'].map(k=>`<div class="annotation-destination">${annotationCheckbox('dest_'+k,{readwise:'Readwise Highlights · send saved passages and notes',reader:'Readwise Reader · send passages to matching EPUBs',crosspoint:'CrossPoint · send passages with device fingerprints'}[k],s.destinations?.[k])}${annotationCheckbox('pause_'+k,'Paused',s.paused?.includes(k))}<small>${k==='crosspoint'?(annotationState.deviceConnected?'Sync credentials available':'Set up device credentials first'):(annotationState.readwiseConnected?'Readwise token saved':'Connect Readwise in Connections first')}</small></div>`).join('')}${annotationCheckbox('importReadwise','Allow importing Readwise highlights',s.importReadwise)}${annotationCheckbox('importProgress','Import reading progress when syncing Readwise Reader',s.importProgress)}<p class="hint">Readwise uses your saved Readwise token. Reader requires a matching EPUB. Service adapters managed by CrossPoint remain managed in CrossPoint. Disconnect in Connections; local highlights remain.</p><button type="button" class="small-btn" onclick="post({type:'syncReadwiseReaderProgress'})">Sync Reader progress with local EPUBs</button></details></fieldset><fieldset><legend>Exports</legend>${select('exportFormat','Format',[['markdown','Markdown'],['csv','CSV'],['json','JSON']])}<label>Filename pattern<input name="filename" value="${esc(s.filename||'')}" maxlength="100"></label><label>Markdown template<textarea name="exportTemplate" rows="5">${esc(s.exportTemplate||'')}</textarea></label><p class="hint">Available fields: {title}, {author}, {date}, {highlights}. Templates are text, never executable code.</p>${annotationCheckbox('exportNotes','Include notes',s.exportNotes)}${annotationCheckbox('exportTags','Include tags',s.exportTags)}${annotationCheckbox('exportLocation','Include source and location',s.exportLocation)}<button type="button" class="small-btn" onclick="annotationPost('chooseExportFolder')">Choose export folder…</button><p class="hint">${esc(annotationState.exportFolder||'No folder selected')}</p>${annotationCheckbox('scheduledExport','Export changed highlights automatically while Shelf is open',s.scheduledExport)}<p class="hint">Automatic exports create Shelf-prefixed files without replacing your existing notes. Each change creates a new snapshot.</p><button type="button" class="small-btn" onclick="annotationExportPreview()">Preview export</button></fieldset><fieldset><legend>Daily review</legend><label>Passages per session<input name="reviewSize" type="number" min="1" max="50" value="${s.reviewSize||5}"></label><div class="annotation-week"><p>Review days</p>${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map((d,i)=>`<label class="annotation-check"><input type="checkbox" name="reviewDay" value="${i}" ${s.reviewDays?.includes(i)?'checked':''}>${d}</label>`).join('')}</div><label>Collection<select name="reviewCollection"><option value="">All highlights</option>${annotationState.collections.map(c=>`<option value="${esc(c.id)}" ${s.reviewCollection===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Exclude tags (comma separated)<input name="excludedTags" value="${esc((s.excludedTags||[]).join(', '))}"></label><label>Exclude Calibre book IDs<input name="excludedBooks" value="${esc((s.excludedBooks||[]).join(', '))}"></label>${annotationCheckbox('reminders','Show an in-app reminder while Shelf is open',s.reminders)}<label>Reminder time<input name="reminderTime" type="time" value="${esc(s.reminderTime||'09:00')}"></label><p class="hint">Frequency can be adjusted for each highlight under Notes & tags. Short passages and Japanese text are included.</p></fieldset><fieldset><legend>Privacy & storage</legend><p>Highlights, notes, collections, preferences, and pending uploads stay on this Mac. Enabled destinations receive only queued passages and their book metadata. Backups include raw captures and local chat history; credentials and pending uploads are excluded.</p><button type="button" class="small-btn" onclick="annotationPost('backup')">Back up annotations…</button><button type="button" class="small-btn" onclick="annotationPost('chooseRestore')">Preview backup restore…</button><p class="hint">Restore merges records and preserves the current library. An archive in Shelf never deletes a source highlight.</p></fieldset><button class="btn primary" type="submit">Save settings</button></form>`}
function annotationExportPreview(){annotationPost('exportPreview',{format:annotationState.settings.exportFormat||'markdown',rules:annotationFilters})}
function annotationData(response){if(!response.ok)return;annotationState={...annotationState,...response};if(response.action==='previewImport'){annotationPreview=response;document.getElementById('annotationImportPreview').innerHTML=`<h3>Import preview · ${response.total} passages</h3><p>Review the first ${response.preview.length}. Records merge by source identity and location; archives stay archived.</p>${response.preview.slice(0,8).map(x=>`<p><b>${esc(x.title||'Untitled')}</b> · ${esc((x.text||'').slice(0,220))}</p>`).join('')}<label>Link imported passages to a book (optional)<select id="annotationImportBook">${annotationBookOptions('','Keep imported book links')}</select></label><button class="btn primary" onclick="annotationPost('applyImport',{bookId:Number(document.getElementById('annotationImportBook').value)||0});document.getElementById('annotationImportDialog').close()">Import / merge</button>`;document.getElementById('annotationImportDialog').showModal()}if(response.action==='exportPreview'){document.getElementById('annotationTextPreview').textContent=response.content||'';document.getElementById('annotationExportDialog').showModal()}if(!annotationsLoaded||response.action==='settings'){annotationFilters.archived=!!response.settings.showArchived;const box=document.querySelector('[name="filterArchived"]');if(box)box.checked=annotationFilters.archived}annotationsLoaded=true;if(response.action==='settings')dashboardNotice({message:'Settings saved'});renderAnnotations();renderReview();renderAnnotationSettings();renderAnnotationConnections();renderReadwiseImport();if(response.added!==undefined)dashboardNotice({message:typeof response.added==='boolean'?(response.added?'Passage saved':'This passage is already saved'):`${response.added} passages added`})}
function initAnnotationUI(){document.getElementById('integrations').insertAdjacentHTML('beforeend','<div id="annotationConnections"></div>');titles.highlights=['Highlights','Your passages, notes, and sources in one place.'];titles.review=['Review','Revisit your own highlights at your own pace.'];titles.preferences=['Settings','Reading, annotations, sync, exports, review, and privacy.'];document.querySelector('footer').insertAdjacentHTML('beforebegin',`<section class="page" id="highlights"><div class="section-head"><div><h2>Highlights</h2><p id="annotationCount">Loading…</p></div><div class="annotation-actions"><button class="btn secondary" onclick="annotationNew()">Add passage</button><button class="btn secondary" onclick="document.getElementById('annotationImportPicker').showModal()">Import…</button><select id="annotationExportFormat"><option value="markdown">Markdown</option><option value="csv">CSV</option><option value="json">JSON</option></select><button class="btn primary" onclick="annotationPost('export',{format:document.getElementById('annotationExportFormat').value,rules:annotationFilters})">Export view…</button></div></div><article class="annotation-card"><div class="section-head"><div><h3>My Readwise library</h3><p id="readwiseImportStatus" role="status" aria-live="polite">Connect once to bring every highlight into Shelf.</p></div><button class="btn primary" id="readwiseImportButton" onclick="startReadwiseImport()">Sync Readwise</button></div><p class="hint">All sources and titles, including those outside your local book library. Imports stay on this Mac; sending highlights elsewhere is optional.</p></article><div class="annotation-toolbar"><label>Search passages, notes, books<input id="annotationSearch" type="search" placeholder="Find a passage…"></label><label>Source<select id="annotationSource"></select></label><label>Tag<select id="annotationTag"></select></label><label>Author<input id="annotationAuthor"></label><label>Book<select id="annotationBook"></select></label>${annotationCheckbox('filterFavorite','Favorites',false)}${annotationCheckbox('filterNotes','With notes',false)}${annotationCheckbox('filterArchived','Include archived',false)}</div><div class="annotation-actions"><div id="annotationCollections"></div><button class="small-btn" onclick="document.getElementById('annotationCollectionDialog').showModal()">Save filters as collection…</button><button class="small-btn" onclick="annotationFilters={search:'',source:'',author:'',tag:'',bookId:'',favorite:false,notes:false,archived:false};annotationResetFilters()">Clear filters</button></div><div id="annotationList" class="annotation-list"></div><button id="annotationMore" class="btn secondary" onclick="annotationLimit+=60;renderAnnotations()">Show more</button><div class="section-head"><div><h3>Pending uploads & history</h3><p>Unconfirmed uploads require checking the destination before retrying.</p></div><button class="btn secondary" onclick="annotationPost('sync')">Sync now</button></div><div id="annotationQueue"></div><div id="annotationConflicts"></div></section><section class="page" id="review"><div class="section-head"><div><h2>Your daily review</h2><p>Your passages only, without streaks or recommendations.</p></div><div><button class="small-btn" onclick="annotationPost('settings',{values:{snoozeUntil:Math.floor(Date.now()/1000)+86400}})">Snooze 24 hours</button><button class="small-btn" onclick="annotationPost('settings',{values:{snoozeUntil:0}})">Resume</button></div></div><div id="annotationReview"></div></section><section class="page" id="preferences"><div class="section-head"><h2>Settings</h2></div><div id="annotationSettings"></div></section>`);
 const nav=document.querySelector('.taskbar');for(const [page,symbol,label] of [['highlights','❞','Highlights'],['review','◈','Review'],['preferences','⚙','Settings']]){const a=document.createElement('a');a.dataset.page=page;a.innerHTML=`<span class="nav-symbol">${symbol}</span><small>${label}</small>`;a.addEventListener('click',()=>{showPage(page);if(!booksData)loadBooks();annotationPost('list')});nav.appendChild(a)}
 document.body.insertAdjacentHTML('beforeend',`<dialog class="annotation-dialog" id="annotationEditor"><form id="annotationEditorForm"><h3 id="annotationEditorTitle">Add passage</h3><input type="hidden" name="id"><label>Book title<input name="title" required maxlength="500"></label><label>Author<input name="author" maxlength="500"></label><label>Passage<textarea name="text" required rows="5" maxlength="20000"></textarea></label><label>Personal note<textarea name="note" rows="3" maxlength="20000"></textarea></label><label>Tags, separated by commas<input name="tags" list="annotationTagSuggestions"></label><datalist id="annotationTagSuggestions"></datalist><label>Linked book<select name="bookId"></select></label><label>Review frequency (0 excludes; 1 normal; 10 frequent)<input name="frequency" type="number" min="0" max="10" value="1" step="0.5"></label><label>Color<select name="color"><option>yellow</option><option>green</option><option>blue</option><option>pink</option></select></label><p class="hint">Passage edits stay in your personal note; source text remains unchanged.</p><button type="submit" class="btn primary">Save</button><button type="button" class="btn secondary" onclick="this.closest('dialog').close()">Cancel</button></form></dialog><dialog class="annotation-dialog" id="annotationImportPicker"><h3>Import highlights</h3><p>Choose a format, then preview before merging. No upload occurs.</p><select id="annotationImportFormat"><option value="json">Shelf / generic JSON</option><option value="koreader">KOReader JSON export</option><option value="kindle">Kindle My Clippings.txt</option><option value="csv">CSV with text, title, author columns</option></select><button class="btn primary" onclick="this.closest('dialog').close();annotationPost('chooseImport',{format:document.getElementById('annotationImportFormat').value})">Choose file…</button><button class="btn secondary" onclick="this.closest('dialog').close()">Cancel</button><hr><p>Apple Books: import available local annotations read-only. Protected PDF markings may be unavailable.</p><button class="small-btn" onclick="this.closest('dialog').close();annotationPost('previewAppleBooks')">Preview Apple Books highlights</button></dialog><dialog class="annotation-dialog" id="annotationImportDialog"><div id="annotationImportPreview"></div><button class="btn secondary" onclick="this.closest('dialog').close()">Cancel</button></dialog><dialog class="annotation-dialog" id="annotationCollectionDialog"><form id="annotationCollectionForm"><h3>Save current filters</h3><label>Collection name<input name="name" required maxlength="100"></label>${annotationCheckbox('pinned','Pin collection',true)}<button class="btn primary">Save collection</button><button type="button" class="btn secondary" onclick="this.closest('dialog').close()">Cancel</button></form></dialog><dialog class="annotation-dialog" id="annotationRetryDialog"><h3>Retry this upload?</h3><p>For an unconfirmed upload, first check the destination. Retrying may create a duplicate if the original request succeeded.</p><button id="annotationConfirmRetry" class="btn primary">I checked · retry</button><button class="btn secondary" onclick="this.closest('dialog').close()">Cancel</button></dialog><dialog class="annotation-dialog" id="annotationExportDialog"><h3>Export preview</h3><pre id="annotationTextPreview"></pre><button class="btn secondary" onclick="this.closest('dialog').close()">Close</button></dialog>`);
 document.getElementById('annotationSearch').addEventListener('input',e=>annotationSelect('search',e.target.value));for(const [id,key] of [['annotationSource','source'],['annotationTag','tag'],['annotationAuthor','author'],['annotationBook','bookId']])document.getElementById(id).addEventListener('change',e=>annotationSelect(key,e.target.value));for(const [name,key] of [['filterFavorite','favorite'],['filterNotes','notes'],['filterArchived','archived']])document.querySelector(`[name="${name}"]`).addEventListener('change',e=>annotationSelect(key,e.target.checked));
 document.addEventListener('submit',e=>{if(e.target.getAttribute('id')==='annotationEditorForm'){e.preventDefault();const f=e.target.elements,changes={note:f.note.value,tags:f.tags.value,bookId:Number(f.bookId.value)||0,frequency:Number(f.frequency.value),color:f.color.value};if(f.id.value)annotationPost('edit',{id:f.id.value,changes});else annotationPost('add',{item:{...changes,title:f.title.value,author:f.author.value,text:f.text.value,source:'Manual'}});document.getElementById('annotationEditor').close()}if(e.target.getAttribute('id')==='annotationCollectionForm'){e.preventDefault();annotationPost('collection',{name:e.target.elements.name.value,pinned:e.target.elements.pinned.checked,rules:{...annotationFilters}});e.target.closest('dialog').close()}if(e.target.getAttribute('id')==='annotationPreferencesForm'){e.preventDefault();const f=e.target.elements,values={};for(const key of ['sort','view','color','exportFormat','filename','exportTemplate','reminderTime','reviewCollection','defaultReader'])values[key]=f[key].value;for(const key of ['suggestTags','showArchived','autoSync','readwiseAutoImport','importReadwise','importProgress','exportNotes','exportTags','exportLocation','reminders','rememberPerBook','restorePosition','scheduledExport'])values[key]=f[key].checked;values.reviewSize=Number(f.reviewSize.value);for(const key of ['excludedTags','excludedBooks'])values[key]=f[key].value.split(',').map(x=>x.trim()).filter(Boolean);values.reviewDays=[...e.target.querySelectorAll('[name="reviewDay"]:checked')].map(x=>Number(x.value));values.destinations=Object.fromEntries(['readwise','reader','crosspoint'].map(k=>[k,f['dest_'+k].checked]));values.paused=['readwise','reader','crosspoint'].filter(k=>f['pause_'+k].checked);annotationPost('settings',{values});dashboardNotice({message:'Saving settings…'})}});
 document.addEventListener('click',e=>{const button=e.target.closest('[data-annotation],[data-collection],[data-retry],[data-review]');if(!button)return;if(button.dataset.collection){const c=annotationState.collections.find(x=>x.id===button.dataset.collection);if(c){annotationFilters={...c.rules};annotationResetFilters()}return}if(button.dataset.retry){const dialog=document.getElementById('annotationRetryDialog');document.getElementById('annotationConfirmRetry').onclick=()=>{annotationPost('retry',{id:button.dataset.retry});dialog.close()};dialog.showModal();return}if(button.dataset.review){const x=annotationState.review[reviewIndex];if(button.dataset.review==='skip'){reviewIndex=(reviewIndex+1)%Math.max(1,annotationState.review.length);renderReview()}else if(x)annotationPost('reviewed',{id:x.id,days:Number(button.dataset.review)});return}const x=annotationState.items.find(x=>x.id===button.dataset.id);if(!x)return;switch(button.dataset.annotation){case'open':annotationPost('open',{item:x});break;case'edit':annotationEdit(x.id);break;case'favorite':annotationPost('edit',{id:x.id,changes:{favorite:!x.favorite}});break;case'archive':annotationPost('edit',{id:x.id,changes:{archived:!x.archived}});break;case'enqueue':annotationPost('enqueue',{id:x.id});break}});
 document.addEventListener('keydown',e=>{if(activePage!=='review'||e.target.closest('input,textarea,select,dialog')||e.metaKey||e.ctrlKey||e.altKey)return;if(e.key==='Enter'){e.preventDefault();document.querySelector('[data-review="7"]')?.click()}if(e.key==='ArrowRight'){e.preventDefault();document.querySelector('[data-review="skip"]')?.click()}});
 pageOrder.splice(0,pageOrder.length,...Object.keys(titles));annotationPost('list');
}
function annotationResetFilters(){document.getElementById('annotationSearch').value=annotationFilters.search||'';document.getElementById('annotationAuthor').value=annotationFilters.author||'';document.getElementById('annotationBook').value=annotationFilters.bookId||'';for(const [name,key]of[['filterFavorite','favorite'],['filterNotes','notes'],['filterArchived','archived']])document.querySelector(`[name="${name}"]`).checked=!!annotationFilters[key];renderAnnotations()}
initAnnotationUI();

function renderAnnotationConnections(){const root=document.getElementById('annotationConnections');if(!root)return;root.innerHTML='<div class="section-head"><div><h3>Annotation connections</h3><p>Direct Shelf connections are separate from integrations managed by CrossPoint.</p></div></div><div class="integration-grid">'+['readwise','reader','crosspoint'].map(dest=>{const jobs=annotationState.queue.filter(j=>j.destination===dest),sent=jobs.filter(j=>j.status==='sent'),pending=jobs.filter(j=>['pending','sending'].includes(j.status)),failed=jobs.filter(j=>['failed','uncertain'].includes(j.status)),paused=annotationState.settings.paused?.includes(dest),enabled=annotationState.settings.destinations?.[dest];return `<article class="connector-card"><h4>${{readwise:'Readwise Highlights',reader:'Readwise Reader',crosspoint:'CrossPoint annotations'}[dest]}</h4><p>${{readwise:'Export saved passages, personal notes, and book metadata.',reader:'Import highlights and progress; export passages, notes, and tags to matching EPUBs.',crosspoint:'Export passages and locations to a book’s device fingerprint.'}[dest]}</p><p>${paused?'Paused':enabled?'Exports enabled':'Exports off'} · ${pending.length} queued · ${failed.length} need attention</p><small>Last successful upload: ${sent.length?esc(new Date(Math.max(...sent.map(j=>j.updated))*1000).toLocaleString()):'None recorded'}</small><div class="annotation-actions"><button class="small-btn" onclick="showPage('preferences');annotationPost('list')">Settings</button><button class="small-btn" onclick="showPage('highlights');annotationPost('list')">Upload history</button></div></article>`}).join('')+'</div>'}

document.addEventListener('click',e=>{const pin=e.target.closest('[data-pin-collection]'),remove=e.target.closest('[data-delete-collection]');if(pin){const c=annotationState.collections.find(x=>x.id===pin.dataset.pinCollection);if(c)annotationPost('collection',{...c,pinned:!c.pinned})}if(remove)annotationPost('deleteCollection',{id:remove.dataset.deleteCollection})});

function renderAnnotationConflicts(){const root=document.getElementById('annotationConflicts');if(!root)return;const conflicts=annotationState.conflicts||[];root.innerHTML=conflicts.length?'<h3>Source changes to review</h3>'+conflicts.map(c=>{const current=annotationState.items.find(x=>x.id===c.highlight);return `<article class="annotation-card"><h4>${esc(current?.title||'Highlight')}</h4><p>Your saved passage</p><blockquote>${esc(current?.text||'')}</blockquote><p>Your note: ${esc(current?.note||'')}</p><p>Incoming passage</p><blockquote>${esc(c.incoming.text)}</blockquote><p>Incoming note: ${esc(c.incoming.note||'')}</p><button class="small-btn" data-conflict="${esc(c.id)}" data-accept="false">Keep my version</button><button class="small-btn" data-conflict="${esc(c.id)}" data-accept="true">Use source passage & note</button></article>`}).join(''):''}
document.addEventListener('click',e=>{const button=e.target.closest('[data-conflict]');if(button)annotationPost('resolve',{id:button.dataset.conflict,accept:button.dataset.accept==='true'})});

// Optional Studio services: no automatic cloud calls and no browser key storage.
let studioState={options:{},captures:[],history:[],tools:{}},studioCapture=null,studioSegment=0;
function studioPost(action,values={}){post({type:'studio',action,...values})}
function studioScope(){const key=document.getElementById('studioScope')?.value;return key==='current'?{...annotationFilters}:annotationState.collections.find(c=>c.id===key)?.rules||{}}
function studioBusy(value){const status=document.getElementById('studioStatus');if(status){status.textContent=value.busy?(value.message||'Working…'):'';status.setAttribute('aria-busy',String(!!value.busy))}document.querySelectorAll('#studio [data-studio-work]').forEach(b=>b.disabled=!!value.busy);const cancel=document.getElementById('studioCancel');if(cancel)cancel.hidden=!value.busy||!value.canCancel}
function studioData(value){studioBusy({busy:false});if(!value.ok){dashboardNotice({message:value.error||'Studio operation failed'});return}studioState={...studioState,...value};if(value.capture){studioCapture=value.capture;studioSegment=0;renderStudioCapture()}if(value.evidence)document.getElementById('studioEvidence').innerHTML=studioEvidenceCards(value.evidence);if(value.notionPreview){const p=value.notionPreview;document.getElementById('studioNotionPreview').innerHTML=`<h4>${p.count} highlights · ${p.pages.length} snapshot pages</h4><p>Exports this view’s passages, personal notes, tags, and book metadata to your configured Notion page.</p>${p.examples.map(x=>`<p><b>${esc(x.title)}</b><br>${esc(x.text)}</p>`).join('')}<p>Snapshots already exported: ${p.pages.filter(x=>x.status==='sent').length}. Unconfirmed snapshots: ${p.pages.filter(x=>x.status==='uncertain').length}.</p>${annotationCheckbox('studioNotionConsent','Send these previewed highlights and notes to Notion',false)}<button data-studio-work class="btn primary" onclick="studioPost('notionExport',{consent:!!document.querySelector('[name=studioNotionConsent]')?.checked})">Export previewed snapshots</button>${p.pages.some(x=>x.status==='uncertain')?`<p>Check Notion first: an unconfirmed snapshot may already exist. An explicit retry can duplicate it.</p><button data-studio-work class="btn secondary" onclick="studioPost('notionExport',{consent:!!document.querySelector('[name=studioNotionConsent]')?.checked,retry:true})">I checked Notion · retry unconfirmed</button>`:''}`}if(value.notionResults)document.getElementById('studioNotionResults').innerHTML=value.notionResults.map(r=>`<p><b>${esc(r.status)}</b> · ${esc(r.message||'Previously exported')}${r.page?` <a target="_blank" rel="noreferrer" href="https://www.notion.so/${esc(r.page.replaceAll('-',''))}">Open snapshot ↗</a>`:''}</p>`).join('');if(value.action==='saveCredential'){document.querySelectorAll('#studio input[type=password]').forEach(x=>x.value='');dashboardNotice({message:'Service key verified and saved locally'})}if(value.action==='settings')dashboardNotice({message:'Studio settings saved'});if(value.action==='saveExcerpt')dashboardNotice({message:'Passage saved in Highlights'});if(value.ocrTotalPages>value.ocrProcessedPages)dashboardNotice({message:`OCR processed ${value.ocrProcessedPages} of ${value.ocrTotalPages} pages. Increase the page limit in Studio settings to process more.`});renderStudioStatus();renderStudioHistory();renderStudioOptions()}
function studioEvidenceCards(items){return items.map(x=>`<article class="annotation-card"><b>[${esc(x.label)}] ${esc(x.title)}</b><blockquote>${esc(x.text)}</blockquote>${x.note?`<p class="annotation-note">${esc(x.note)}</p>`:''}<button class="small-btn" data-studio-source="${esc(x.id)}">Open source</button></article>`).join('')||'<p class="hint">No matching highlights. Try different words or choose a narrower collection.</p>'}
function renderStudioStatus(){const root=document.getElementById('studioConnections');if(!root)return;root.textContent=`Notion: ${studioState.notionConnected?'key saved':'not connected'} · OpenAI: ${studioState.openaiConnected?'key saved':'not connected'} · Audio: ${studioState.audioName||'none selected'}`;document.getElementById('studioTools').textContent=`whisper.cpp: ${studioState.tools.whisperExecutable||'Not selected'} · Model: ${studioState.tools.whisperModel||'Not selected'} · ffmpeg: ${studioState.tools.ffmpegExecutable||'Not selected'}`;const provider=studioState.options.chatProvider||'ollama';document.getElementById('studioChatMode').textContent=provider==='ollama'?'Local Ollama · no external upload':'OpenAI · selected evidence and your question leave this Mac';document.getElementById('studioAudioMode').textContent=studioState.options.transcriptionProvider==='openai'?'OpenAI transcription · audio upload, under 24 MB':'Local whisper.cpp · audio stays on this Mac';const scope=document.getElementById('studioScope');const selected=scope.value;scope.innerHTML='<option value="">Matching highlights across the library</option><option value="current">Current Highlights filters</option>'+annotationState.collections.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');scope.value=selected;document.getElementById('studioCaptures').innerHTML=studioState.captures.map(c=>`<button class="small-btn" data-studio-capture="${esc(c.id)}">${esc(c.kind)} · ${esc(c.title)}</button>`).join('')||'<p class="hint">No captures yet. Scan an image/PDF or transcribe a downloaded audio file.</p>'}
function renderStudioCapture(){const root=document.getElementById('studioCapture');if(!studioCapture){root.innerHTML='';return}const part=studioCapture.segments[studioSegment];root.innerHTML=`<h3>${esc(studioCapture.title)}</h3><label>Page / transcript segment<select id="studioSegment">${studioCapture.segments.map((s,i)=>`<option value="${i}" ${i===studioSegment?'selected':''}>${studioCapture.kind==='OCR'?'Page '+s.page:studioTime(s.start)+' – '+studioTime(s.end)}</option>`).join('')}</select></label><label>Review and edit a passage<textarea id="studioExcerpt" rows="9" maxlength="20000">${esc(part.text.slice(0,20000))}</textarea></label><p class="hint">Save up to 20,000 characters as one highlight. Full captured text remains available to export. OCR and transcripts can contain mistakes.</p><label>Personal note<textarea id="studioExcerptNote" rows="2"></textarea></label><label>Tags<input id="studioExcerptTags" placeholder="podcast, research"></label><label>Link to a local book (optional)<select id="studioExcerptBook">${annotationBookOptions('','Not linked')}</select></label><div class="annotation-actions"><button data-studio-work class="btn primary" onclick="studioPost('saveExcerpt',{id:studioCapture.id,index:studioSegment,text:document.getElementById('studioExcerpt').value,note:document.getElementById('studioExcerptNote').value,tags:document.getElementById('studioExcerptTags').value.split(','),bookId:Number(document.getElementById('studioExcerptBook').value)||0})">Save passage to Highlights</button><button data-studio-work class="btn secondary" onclick="studioPost('exportCapture',{id:studioCapture.id})">Export full text…</button><button class="small-btn" onclick="document.getElementById('studioDeleteCapture').showModal()">Delete capture…</button></div>`;document.getElementById('studioSegment').addEventListener('change',e=>{studioSegment=Number(e.target.value);renderStudioCapture()})}
function studioTime(seconds){const n=Math.max(0,Math.floor(Number(seconds)||0));return [Math.floor(n/3600),Math.floor(n/60)%60,n%60].map(x=>String(x).padStart(2,'0')).join(':')}
function renderStudioHistory(){document.getElementById('studioChatHistory').innerHTML=studioState.history.map(c=>`<article class="annotation-card"><p class="hint">${esc(c.provider)} · ${esc(new Date(c.created*1000).toLocaleString())}</p><h4>${esc(c.question)}</h4><p class="studio-answer">${esc(c.answer)}</p><details><summary>Supporting passages · ${c.citations.length}</summary>${studioEvidenceCards(c.citations)}</details><p class="hint">Citations identify supplied passages; they do not guarantee the model interpreted them correctly.</p></article>`).join('')}
function renderStudioOptions(){const root=document.getElementById('studioOptions');if(root.contains(document.activeElement))return;const o=studioState.options;root.innerHTML=`<form id="studioSettingsForm" class="annotation-settings"><fieldset><legend>Notion destination</legend><label>Parent page link or ID<input name="notionParent" value="${esc(o.notionParent||'')}" placeholder="https://www.notion.so/your-page-id"></label><p>Share this page with your Notion integration first. Exports create new snapshot pages underneath it; existing pages and personal edits are preserved.</p></fieldset><fieldset><legend>Chat model</legend><label>Provider<select name="chatProvider"><option value="ollama" ${o.chatProvider==='ollama'?'selected':''}>Local Ollama</option><option value="openai" ${o.chatProvider==='openai'?'selected':''}>OpenAI</option></select></label><label>Model name<input name="chatModel" value="${esc(o.chatModel||'llama3.2:3b')}" required></label><label>Maximum matching passages<input name="chatContext" type="number" min="1" max="20" value="${o.chatContext||8}"></label><p>Local chat uses Ollama on this Mac at port 11434. Install and download your chosen model separately. For OpenAI, choose an available model such as gpt-4.1-mini.</p></fieldset><fieldset><legend>OCR</legend><label>Languages<select name="ocrLanguages" multiple size="5">${[['en-US','English'],['ja-JP','Japanese'],['de-DE','German'],['fr-FR','French'],['es-ES','Spanish'],['zh-Hans','Simplified Chinese'],['zh-Hant','Traditional Chinese'],['ko-KR','Korean']].map(([v,n])=>`<option value="${v}" ${o.ocrLanguages?.includes(v)?'selected':''}>${n}</option>`).join('')}</select></label><label>Maximum PDF pages<input type="number" min="1" max="50" name="ocrPages" value="${o.ocrPages||10}"></label><p>Images and PDFs are processed locally with Apple Vision. Review recognition errors before saving excerpts. OCR does not upload images.</p></fieldset><fieldset><legend>Podcast transcription</legend><label>Provider<select name="transcriptionProvider"><option value="local" ${o.transcriptionProvider==='local'?'selected':''}>Local whisper.cpp</option><option value="openai" ${o.transcriptionProvider==='openai'?'selected':''}>OpenAI audio upload</option></select></label><label>Audio language<input name="transcriptionLanguage" value="${esc(o.transcriptionLanguage||'auto')}" placeholder="auto, en, ja"></label><p>Local mode requires whisper.cpp, an authentic GGML model, and ffmpeg. Select these files below; Shelf does not install or run an unselected download.</p></fieldset><button data-studio-work class="btn primary" type="submit">Save Studio settings</button></form>`}
function initStudio(){titles.studio=['Studio','Capture text, transcribe audio, ask your highlights, and export to Notion.'];pageOrder.push('studio');document.querySelector('footer').insertAdjacentHTML('beforebegin',`<section id="studio" class="page"><div class="section-head"><div><h2>Reading Studio</h2><p id="studioConnections">Loading local settings…</p></div><button class="small-btn" data-studio-work onclick="studioPost('status')">Refresh</button></div><div role="status" aria-live="polite" id="studioStatus"></div><button class="btn secondary" id="studioCancel" hidden onclick="studioPost('cancel')">Cancel local processing</button><div class="studio-grid"><article class="annotation-card"><h3>Scan pages & images</h3><p>Recognize text in an image or PDF on this Mac, then save corrected passages to Highlights.</p><button data-studio-work class="btn primary" onclick="studioPost('chooseOCR')">Choose image or PDF…</button><h3>Podcast transcription</h3><p id="studioAudioMode"></p><div class="annotation-actions"><button data-studio-work class="btn secondary" onclick="studioPost('chooseAudio')">Choose downloaded audio…</button><button data-studio-work class="btn secondary" onclick="studioPost('chooseTranscript')">Import TXT / SRT / VTT…</button></div>${annotationCheckbox('studioCloudAudio','Allow uploading the selected audio to OpenAI for this transcription',false)}<button data-studio-work class="btn primary" onclick="studioPost('transcribe',{consent:!!document.querySelector('[name=studioCloudAudio]').checked})">Transcribe selected audio</button><h4>Local transcription tools</h4><p id="studioTools"></p><div class="annotation-actions"><button data-studio-work class="small-btn" onclick="studioPost('chooseTool',{kind:'whisperExecutable'})">Choose whisper.cpp…</button><button data-studio-work class="small-btn" onclick="studioPost('chooseTool',{kind:'whisperModel'})">Choose GGML model…</button><button data-studio-work class="small-btn" onclick="studioPost('chooseTool',{kind:'ffmpegExecutable'})">Choose ffmpeg…</button></div><p class="hint">Local processing can be cancelled. Cloud requests may finish or be billed even if a connection is interrupted.</p></article><article class="annotation-card studio-fields"><h3>Captures & transcripts</h3><div id="studioCaptures"></div><div id="studioCapture"></div></article></div><div class="section-head"><h3>Chat with your highlights</h3></div><div class="annotation-card studio-fields"><p id="studioChatMode"></p><label>Evidence scope<select id="studioScope"><option value="">Matching highlights across the library</option></select></label><form id="studioChatForm"><label>Question<textarea name="question" id="studioQuestion" required maxlength="4000" rows="3" placeholder="What did I save about reading habits?"></textarea></label>${annotationCheckbox('studioCloudChat','Allow sending this question and matching passages, including personal notes, to OpenAI',false)}<div class="annotation-actions"><button data-studio-work class="btn secondary" type="button" onclick="studioPost('retrieve',{question:document.getElementById('studioQuestion').value,rules:studioScope()})">Preview matching passages</button><button data-studio-work class="btn primary" type="submit">Ask selected model</button><button data-studio-work class="small-btn" type="button" onclick="studioPost('clearChats')">Clear local chat history</button></div></form><p class="hint">Only retrieved passages are supplied to the model. Answers are suggestions; use source citations to check them. Your chat history stays on this Mac.</p><div id="studioEvidence"></div></div><div id="studioChatHistory"></div><div class="section-head"><h3>Notion export</h3></div><div class="annotation-card"><p>Export the current Highlights view as new snapshot pages. Choose filters in Highlights first. No export runs automatically.</p><button data-studio-work class="btn secondary" onclick="studioPost('notionPreview',{rules:{...annotationFilters}})">Preview current view for Notion</button><div id="studioNotionPreview"></div><div id="studioNotionResults"></div></div><div class="section-head"><h3>Service keys</h3></div><div class="studio-grid">${[['notion','Notion integration token'],['openai','OpenAI API key']].map(([id,label])=>`<form class="annotation-card studio-fields" data-studio-credential="${id}"><label>${label}<input name="credential" type="password" autocomplete="off" required></label><p class="hint">Stored in Shelf’s private local credential file. Verification contacts only this service; no highlights or audio are sent.</p><button data-studio-work class="btn secondary" type="submit">Verify & save ${id==='notion'?'Notion':'OpenAI'} key</button><button data-studio-work class="small-btn" type="button" onclick="studioPost('disconnect',{provider:'${id}'})">Disconnect</button></form>`).join('')}</div><div class="section-head"><h3>Studio settings</h3></div><div id="studioOptions"></div></section>`);
 document.body.insertAdjacentHTML('beforeend','<dialog class="annotation-dialog" id="studioDeleteCapture"><h3>Delete this capture?</h3><p>The raw OCR text or transcript will be removed locally. Passages already saved in Highlights remain.</p><button class="btn primary" onclick="studioPost(\'deleteCapture\',{id:studioCapture.id});studioCapture=null;renderStudioCapture();this.closest(\'dialog\').close()">Delete capture</button><button class="btn secondary" onclick="this.closest(\'dialog\').close()">Cancel</button></dialog>');
 const tab=document.createElement('a');tab.dataset.page='studio';tab.innerHTML='<span class="nav-symbol">✧</span><small>Studio</small>';tab.addEventListener('click',()=>{showPage('studio');if(!booksData)loadBooks();studioPost('status')});document.querySelector('.taskbar').appendChild(tab);
 document.addEventListener('submit',e=>{const form=e.target;if(form.getAttribute('id')==='studioSettingsForm'){e.preventDefault();const f=form.elements;studioPost('settings',{values:{notionParent:f.notionParent.value,chatProvider:f.chatProvider.value,chatModel:f.chatModel.value,chatContext:Number(f.chatContext.value),ocrLanguages:[...f.ocrLanguages.selectedOptions].map(x=>x.value),ocrPages:Number(f.ocrPages.value),transcriptionProvider:f.transcriptionProvider.value,transcriptionLanguage:f.transcriptionLanguage.value}})}if(form.getAttribute('id')==='studioChatForm'){e.preventDefault();studioPost('chat',{question:form.elements.question.value,rules:studioScope(),consent:form.elements.studioCloudChat.checked})}if(form.dataset.studioCredential){e.preventDefault();studioPost('saveCredential',{provider:form.dataset.studioCredential,value:form.elements.credential.value})}});
 document.addEventListener('click',e=>{const capture=e.target.closest('[data-studio-capture]');if(capture)studioPost('getCapture',{id:capture.dataset.studioCapture});const source=e.target.closest('[data-studio-source]');if(source){const item=annotationState.items.find(x=>x.id===source.dataset.studioSource)||studioState.history.flatMap(x=>x.citations).find(x=>x.id===source.dataset.studioSource);if(item)annotationPost('open',{item})}});
}
initStudio();

// Sparkle owns these preferences; they are not duplicated in annotation storage.
document.getElementById('updates').insertAdjacentHTML('afterbegin',`<article class="annotation-card" id="shelfUpdateSettings"><h3>Shelf app updates</h3><p id="shelfUpdateVersion">Loading updater settings…</p><label class="annotation-check"><input type="checkbox" id="shelfUpdateChecks">Check for updates automatically</label><label class="annotation-check"><input type="checkbox" id="shelfUpdateDownloads">Download and install updates automatically</label><p class="hint">Updates are checked about every four hours while Shelf is running. Sparkle verifies signed releases and handles installation and relaunch. Automatic installation may wait until you quit, and macOS can request authorization.</p><button class="btn primary" id="shelfCheckNow" onclick="post({type:'checkShelfUpdates'})">Check for Shelf updates…</button></article>`);
window.updatePreferences=value=>{document.getElementById('shelfUpdateVersion').textContent=`Shelf ${value.version}${value.configured?'':' · Update-signing setup required for this build'}`;document.getElementById('shelfUpdateChecks').checked=!!value.checks;document.getElementById('shelfUpdateDownloads').checked=!!value.downloads;document.getElementById('shelfUpdateChecks').disabled=!value.configured;document.getElementById('shelfUpdateDownloads').disabled=!value.configured||!value.checks;document.getElementById('shelfCheckNow').disabled=!value.configured};
for(const id of ['shelfUpdateChecks','shelfUpdateDownloads'])document.getElementById(id).addEventListener('change',()=>post({type:'saveUpdatePreferences',checks:document.getElementById('shelfUpdateChecks').checked,downloads:document.getElementById('shelfUpdateDownloads').checked}));

function startReadwiseImport(){if(!(annotationState.readwiseConnected||data?.readwiseConnected)){showPage('integrations');document.getElementById('readwiseTokenInput')?.focus();dashboardNotice({message:'Connect Readwise once. Your full library will import automatically.'});return}const status=document.getElementById('readwiseImportStatus');if(status)status.textContent='Checking Readwise for highlights…';annotationPost('importReadwise')}
function renderReadwiseImport(){const root=document.getElementById('readwiseImportStatus');if(!root)return;const state=annotationState.readwiseSync||{},connected=annotationState.readwiseConnected||data?.readwiseConnected;const count=annotationState.items.filter(x=>x.source==='Readwise').length;root.textContent=!connected?'Connect once to import every highlight from Readwise.':`${count.toLocaleString()} Readwise highlights saved · ${state.message||'Ready to import your library.'}${state.inProgress?' · '+Number(state.processed||0).toLocaleString()+' processed':''}${state.lastSuccess?' · Last completed '+new Date(state.lastSuccess*1000).toLocaleString():''}`;document.getElementById('readwiseImportButton').textContent=connected?'Sync now':'Connect Readwise';const connection=document.getElementById('readwiseConnectionStatus');if(connection&&connected)connection.textContent=state.message||'Connected · highlights import automatically';}
